import{z as n,x as o,o as e,c as p,q as i,j as t,D as a,d as A,s as l,S as s,b as B}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"技术报告的判读","description":"","frontmatter":{"title":"技术报告的判读","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rw-report-reading.md","filePath":"llm/rw-report-reading.md","lastUpdated":1791413859000}'),d={name:"llm/rw-report-reading.md"};function D(h,E,c,m,C,f){const r=o("Mermaid");return e(),p("div",null,[E[2]||(E[2]=i('<h1 id="技术报告的判读" tabindex="-1">技术报告的判读 <a class="header-anchor" href="#技术报告的判读" aria-label="Permalink to &quot;技术报告的判读&quot;">​</a></h1><div class="epigraph"><p>正文负责说服你结论成立，附录才负责告诉你它怎么被造出来；只读正文的复现，复现的是叙事而不是实验。</p><footer>—— 据 Lipton 与 Steinhardt, Troubling Trends in Machine Learning Scholarship, 2019 整理</footer></div><p><a href="/llm/rw-replication-types">上一课</a>把复现分成类型与目标线，开工前先写一页声明。声明的类型一旦定了，第一件事不是写代码，而是判读报告：从论文或技术报告里抽出作者的决策清单，并给每一项标上披露档位。预训练配方的对照课<a href="/llm/pf2-opensource-recipes">开源配方对照</a>已经给了口径——读报告抽决策、不抄数字；本课把它展开成复现工作流里的可操作次序。判读的产出是一张表，后课的走读、消融与对齐都以它为对照面。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>报告是存档与营销的混合体。主表数字属于一个坐标系：训练数据快照、分词器、评测协议、提示模板、few-shot 数量；离开坐标系，数字没有语义。判读的第一缺口因此不是「结论可信吗」，而是「每个数字绑在哪套坐标系上」。第二缺口是决策与叙事的分离：论文讲因果故事的句子，和真正决定结果的工程选择，往往不在同一段。把叙事当决策抄下来，复现会花算力去验证一个修辞。</p><p><span class="marginnote">「坐标系」可以类比食品包装上的保质期与储存条件：脱离那行小字，「还可保存 30 天」没有意义。主表数字同理——离开「哪份数据、哪个分词器、哪个协议」，80.5 分什么也说明不了。</span></p><p>判读失败的模式很固定：只读正文、只抄主表、把超参表当成全部超参（表里常只列优化器，不列数据清洗与去重阈值）、忽略「评测用哪一版 checkpoint」的脚注。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>判读按固定次序走。第一步读声明：数据来源与许可、规模、计算预算、评测协议的披露位置。第二步抽决策表，按<a href="/llm/pf2-opensource-recipes">开源配方对照</a>的六行：规模分割、配比管线、超参迁移、日程退火、稳定件、评估声明；每行标披露档位——显式给出、隐式可推、完全缺失。缺失要分性质：能力问题（作者没做记录）与刻意保密（数据或配方不公开），两者对复现策略的含义不同，前者可以从仓库与 issue 里挖，后者只能换目标线。第三步对每个主表数字回填坐标系：哪份数据、哪个 checkpoint、哪个协议；回填不上坐标系的数字记为「不可对齐」，不进入验收判据。</p><p>超参表按「在全量规模调出、向小模型外推」判读：直接照搬到缩小规模会先误判配比再误判方法，这条在算力预算一课处理。附录里的清洗、去重与评测脚本引用，比正文的公式更常决定成败。</p><p><span class="marginnote">常见误区：把论文的超参表当成全部超参。表里通常只列学习率这类优化器参数，数据清洗顺序、去重阈值、评测用哪一版 checkpoint 常藏在附录或脚注里——漏看一行，后面的对齐就会一直「差一点」。</span></p>',11)),(e(),t(s,null,{default:a(()=>[l(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20RPT%5B%22%E6%8A%A5%E5%91%8A%E4%B8%8E%E9%99%84%E5%BD%95%22%5D%20--%3E%20DEC%5B%22%E5%86%B3%E7%AD%96%E8%A1%A8%EF%BC%9A%E5%85%AD%E8%A1%8C%22%5D%0A%20%20DEC%20--%3E%20GRADE%5B%22%E6%A0%87%E6%B3%A8%E6%8A%AB%E9%9C%B2%E6%A1%A3%E4%BD%8D%22%5D%0A%20%20GRADE%20--%3E%20COORD%5B%22%E6%95%B0%E5%AD%97%E5%9B%9E%E5%A1%AB%E5%9D%90%E6%A0%87%E7%B3%BB%22%5D%0A%20%20COORD%20--%3E%20GAP%7B%22%E7%BC%BA%E5%A4%B1%E8%A1%8C%E7%9A%84%E6%80%A7%E8%B4%A8%22%7D%0A%20%20GAP%20--%3E%7C%22%E8%83%BD%E5%8A%9B%E9%97%AE%E9%A2%98%22%7C%20DIG%5B%22%E6%8C%96%E4%BB%93%E5%BA%93%E4%B8%8E%20issue%22%5D%0A%20%20GAP%20--%3E%7C%22%E5%88%BB%E6%84%8F%E4%BF%9D%E5%AF%86%22%7C%20SHIFT%5B%22%E9%99%8D%E7%BA%A7%E7%9B%AE%E6%A0%87%E7%BA%BF%22%5D%0A%20%20DIG%20--%3E%20BASE%5B%22%E5%AF%B9%E7%85%A7%E9%9D%A2%EF%BC%9A%E4%BE%9B%E5%A4%8D%E7%8E%B0%E5%AF%B9%E9%BD%90%22%5D%0A%20%20SHIFT%20--%3E%20BASE%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B("h2",{id:"机制",tabindex:"-1"},[A("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=B("p",null,"为什么报告不能当代码的可靠描述：报告写作滞后于最后一次实验。经过多轮迭代后，作者汇报的是最后一代配置，中间被推翻的尝试不写，仓库里却留着死代码与多代路径；所以判读的结论必须与仓库对质，这正是下一课走读的任务。判读与走读的分工是：判读产出「作者声称做了什么」，走读产出「代码实际做了什么」，两张表的 diff 就是风险清单。",-1)),(e(),t(s,null,{default:a(()=>[l(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20P%5B%22%E5%88%A4%E8%AF%BB%EF%BC%9A%E4%BD%9C%E8%80%85%E5%A3%B0%E7%A7%B0%E5%81%9A%E4%BA%86%E4%BB%80%E4%B9%88%22%5D%20--%3E%20D%5B%22%E4%B8%A4%E5%BC%A0%E8%A1%A8%E5%81%9A%20diff%22%5D%0A%20%20C%5B%22%E8%B5%B0%E8%AF%BB%EF%BC%9A%E4%BB%A3%E7%A0%81%E5%AE%9E%E9%99%85%E5%81%9A%E4%BA%86%E4%BB%80%E4%B9%88%22%5D%20--%3E%20D%0A%20%20D%20--%3E%20S1%5B%22%E4%B8%80%E8%87%B4%E9%A1%B9%EF%BC%9A%E5%8F%AF%E4%BF%A1%EF%BC%8C%E8%BF%9B%E5%AF%B9%E7%85%A7%E9%9D%A2%22%5D%0A%20%20D%20--%3E%20S2%5B%22%E5%86%B2%E7%AA%81%E9%A1%B9%EF%BC%9A%E8%BF%9B%E9%A3%8E%E9%99%A9%E6%B8%85%E5%8D%95%E4%BC%98%E5%85%88%E6%A0%B8%E6%9F%A5%22%5D%0A%20%20D%20--%3E%20S3%5B%22%E5%A3%B0%E7%A7%B0%E6%9C%89%E3%80%81%E4%BB%A3%E7%A0%81%E6%97%A0%EF%BC%9A%E7%96%91%E4%BC%BC%E5%8F%99%E4%BA%8B%22%5D%0A%20%20D%20--%3E%20S4%5B%22%E4%BB%A3%E7%A0%81%E6%9C%89%E3%80%81%E5%A3%B0%E7%A7%B0%E6%97%A0%EF%BC%9A%E9%9A%90%E6%80%A7%E5%86%B3%E7%AD%96%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=i('<p><span class="marginnote">直觉类比：把报告想成装修完工照——拍到的是最后定稿的样子，中途拆掉重来的墙不会出现在照片里，但旧图纸（仓库里的死代码）还留着。所以「声称」必须与「实际」对质，不能只信照片。</span></p><p>数字回填坐标系还有一层机制含义：相同 loss 的两个模型，分词器不同则不可比；相同基准的两个分数，提示模板不同可以差出好几个点。坐标系不齐就做比较，是复现对不上时的头号假线索——失败归因一课把它排在所有嫌疑之首。</p><p><span class="marginnote">Melis 等 2018 在字符级语言建模上重审多个「新架构」：把基线 LSTM 的规模与正则调平后，多数新方法的增益消失。判读时先问「基线调到什么程度」，再看主表的领先幅度，顺序不能反。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>判读不是审稿：目标是支撑复现，不是给论文打分；发现的披露缺口写成风险行即可，不必展开成批评。也不要把博客补丁与后见之明混进判读：论文发布后仓库继续变化，已修复的 bug 会让「现在的代码」偏离「论文时刻的代码」，一切以与论文对应的 tag 或提交为冻结点，报告与仓库冲突时记录冲突而不是各信一半。第三方转述（新闻、知乎、推文）不进决策表；同一信息必须追到一手来源才落档。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>判读产出决策表：六行对照，每行标显式、隐式、缺失三档。</li><li>每个主表数字必须回填坐标系，回填不上的记为不可对齐，不进验收判据。</li><li>缺失分性质：能力问题可挖仓库，刻意保密要降级目标线。</li><li>判读与走读分工：声称与实际的 diff 就是复现的风险清单。</li><li>出处：Lipton 与 Steinhardt, 2019；Melis 等, 2018；对照口径见<a href="/llm/pf2-opensource-recipes">开源配方对照</a>。</li></ul>',7))])}const _=n(d,[["render",D]]);export{F as __pageData,_ as default};
